    this._sessionsStats$.next(sessionsStats);
  }

  private replaceCheckedSessions(sessionsToCheck: TestSession[]): void {
    const newCheckedSessions: TestSessionByDataTestId = {};
    sessionsToCheck
      .forEach(session => {
        newCheckedSessions[session.data.testId] = session;
      });
    this._checked = newCheckedSessions;
    this.onCheckedChanged();
  }

  private onCheckedChanged(): void {
    this._checkedStats$.next(TestSessionManager.getSessionSetStats(this.checked, this.sessions.length));
  }
}
import type { TestSessionChange } from '../../common/test-session-change.interface';
import {
  type Booklet,
  type BookletError, isBooklet,
  isUnit,
  type Testlet,
  type TestSession,
  type TestSessionData,
  type TestSessionSuperState,
  type UnitContext
} from '../group-monitor.interfaces';

export class TestSessionUtil {
  static bookletStateLabel(session: TestSession, stateId: string): string | undefined {
    const state = isBooklet(session.booklet) ? session.booklet.states[stateId] : undefined;
    const option = session.bookletStates?.[stateId] || state?.default;
    return option ? state?.options[option]?.label : undefined;
  }

  static hasState(state: Record<string, unknown>, key: string, value: string | null = null): boolean {
    return ((typeof state[key] !== 'undefined') && ((value !== null) ? (state[key] === value) : true));
  }

  static isPaused(session: TestSession): boolean {
    return TestSessionUtil.hasState(session.data.testState, 'CONTROLLER', 'PAUSED');
  }

  static isLocked(session: TestSession): boolean {
    return TestSessionUtil.hasState(session.data.testState, 'status', 'locked');
  }

  static analyzeTestSession(session: TestSessionChange, booklet: Booklet | BookletError): TestSession {
    const current = (isBooklet(booklet) && session.unitName) ?
      TestSessionUtil.getCurrent(booklet.units, session.unitName) :
      null;
    return {
      data: session,
      state: TestSessionUtil.getSuperState(session),
      current: current && current.unit ? current : null,
      booklet,
      timeLeft: TestSessionUtil.parseJsonState<{ [timerId: string]: number }>(session.testState, 'TESTLETS_TIMELEFT'),
      clearedCodes: TestSessionUtil.parseJsonState<string[]>(session.testState, 'TESTLETS_CLEARED_CODE'),
      bookletStates: TestSessionUtil.parseJsonState<{ [state: string]: string }>(session.testState, 'BOOKLET_STATES')
    };
  }

  static stateString(state: Record<string, string>, keys: string[], glue = ''): string {
    return keys
      .map((key: string) => (TestSessionUtil.hasState(state, key) ? state[key] : null))
      .filter(value => value !== null)
      .join(glue);
  }

  private static getSuperState(session: TestSessionData): TestSessionSuperState {
    const state = session.testState;

    if (this.hasState(state, 'status', 'pending')) {
      return 'pending';
    }
    if (this.hasState(state, 'status', 'locked')) {
      return 'locked';
    }
    if (this.hasState(state, 'CONTROLLER', 'ERROR')) {
      return 'error';
    }
    if (this.hasState(state, 'CONTROLLER', 'TERMINATED')) {
      return 'controller_terminated';
    }
    if (this.hasState(state, 'CONTROLLER', 'TERMINATED_PAUSED')) {
      return 'controller_terminated';
    }
    if (this.hasState(state, 'CONNECTION', 'LOST')) {
      return 'connection_lost';
    }
    if (this.hasState(state, 'CONTROLLER', 'PAUSED')) {
      return 'paused';
    }
    if (this.hasState(state, 'FOCUS', 'HAS_NOT')) {
      return 'focus_lost';
    }
    if (TestSessionUtil.idleSinceMinutes(session) > 5) {
      return 'idle';
    }
    if (this.hasState(state, 'CONNECTION', 'WEBSOCKET')) {
      return 'connection_websocket';
    }
    if (this.hasState(state, 'CONNECTION', 'POLLING')) {
      return 'connection_polling';
    }
    return 'ok';
  }

  private static idleSinceMinutes(testSession: TestSessionData): number {
    return (Date.now() - testSession.timestamp * 1000) / (1000 * 60);
  }

  private static parseJsonState<T>(testStateObject: Record<string, string>, key: string): T | null {
    if (typeof testStateObject[key] === 'undefined') {
      return null;
    }

    const stateValueString = testStateObject[key];

    try {
      return JSON.parse(stateValueString);
    } catch (error) {
      return null;
    }
  }

  private static getCurrent(
    testlet: Testlet,
    searchUnitId: string,
    level = 0,
    context: UnitContext | null = null
  ): UnitContext {
    const result: UnitContext = context ?? {
      unit: undefined,
      parent: testlet,
      ancestor: testlet,
      indexGlobal: -1,
      indexLocal: -1,
      indexAncestor: -1
    };

    for (let i = 0; i < testlet.children.length; i++) {
      const child = testlet.children[i];
      if (isUnit(child)) {
        result.indexLocal += 1;
        result.indexAncestor += 1;
        result.indexGlobal += 1;

        if (child.alias === searchUnitId) {
          result.unit = child;
          return result;
        }
      } else {
        const subResult = TestSessionUtil.getCurrent(child, searchUnitId, level + 1, {
          unit: undefined,
          parent: child,
          ancestor: level < 1 ? child : result.ancestor,
          indexGlobal: result.indexGlobal,
          indexLocal: -1,
          indexAncestor: level < 1 ? -1 : result.indexAncestor
        });
        if (subResult.unit) {
          return subResult;
        }
        result.indexGlobal = subResult.indexGlobal;
        result.indexAncestor = level < 1 ? result.indexAncestor : subResult.indexAncestor;
      }
    }

    return result;
  }
}

@if (!originalId) {
  <p
    mat-dialog-title
    data-cy="comment-diag-title"
  >Neuen Filter hinzufügen</p>
}

@if (originalId) {
  <p
    mat-dialog-title
    data-cy="comment-diag-title"
  >Filter bearbeiten</p>
}

<mat-dialog-content>
  <p>Folgende Test-Sitzungen sollen herausgefiltert werden:</p>

  <mat-form-field appearance="outline">
    <mat-label>Feld</mat-label>
    <mat-select [(ngModel)]="filter.target" (ngModelChange)="updateFilterId()" data-cy = "GM_filtersetting_field">
      @for (target of targets.all; track target) {
        @if (advancedMode || !isAdvancedTestSessionFilterTarget(target) || target == filter.target) {
          <mat-option [value]="target" data-cy="column-selection">
            {{(customtext((''),('gm_col_' + target))) || (customtext((target),('gm_filter_target_' + target))) }}
          </mat-option>
        }
      }
    </mat-select>
  </mat-form-field>

  @if (filter.target !== 'state') {
    <mat-form-field appearance="outline">
      <mat-label>Filtertyp</mat-label>
      <mat-select [(ngModel)]="filter.type" (ngModelChange)="validate(); updateFilterId()" data-cy = "GM_filtersetting_type">
        @for (type of filterTypes.all; track type) {
          @if (advancedMode || !isAdvancedTestSessionFilterType(type) || type == filter.type) {
            <mat-option [value]="type">
              {{customtext((type),('gm_filter_type_' + type))}}
            </mat-option>
          }
        }
      </mat-select>
    </mat-form-field>
  }

  <p>
    @if (advancedMode) {
      <mat-slide-toggle [(ngModel)]="filter.not" (ngModelChange)="updateFilterId()">
        {{customtext(('Nicht'),('gm_filter_not'))}}
      </mat-slide-toggle>
    }
  </p>

  @if (filter.target !== 'state') {
    <mat-form-field appearance="outline">
      <mat-label>Filter</mat-label>
      <input
        type="text"
        matInput
        [(ngModel)]="filter.value"
        (ngModelChange)="validate(); updateFilterId()"
        [matAutocomplete]="auto2"
        placeholder=""
        data-cy="comment-diag-value"
        required
        >
      <mat-autocomplete #auto2="matAutocomplete">
        @for (option of lists[filter.target]; track option) {
          <mat-option [value]="option">
            {{ (subValueLists[filter.target]?.[option]) ? subValueLists[filter.target]?.[option]?.label : option}}
          </mat-option>
        }
      </mat-autocomplete>
      @if (!isValid) {
        <tc-alert level="error" text="Ungültiger Wert" />
      }
    </mat-form-field>
  }

  @if (filter.target === 'testState' || filter.target === 'bookletStates') {
    <mat-form-field appearance="outline">
      <mat-label>Unterfilter</mat-label>
      <input
        type="text"
        matInput
        [(ngModel)]="filter.subValue"
        (ngModelChange)="updateFilterId()"
        placeholder=""
        data-cy="comment-diag-subValue"
        required
        [matAutocomplete]="auto3"
        >
      <mat-autocomplete #auto3="matAutocomplete">
        @if (!isStringArray(filter.value)) {
          @if (subValueLists[filter.target]; as list) {
            @if (list[filter.value]; as subValueSelect) {
              @for (option of entries((subValueSelect.options)); track option) {
                <mat-option [value]="option.key">
                  {{ option.value.label }}
                </mat-option>
              }
            }
          }
        }
      </mat-autocomplete>
    </mat-form-field>
  }

  @if (filter.target === 'state') {
    <mat-form-field appearance="outline">
      <mat-label>Filter</mat-label>
      <mat-select [(ngModel)]="filter.value" (ngModelChange)="updateFilterId()" multiple>
        @for (superState of entries((superStates)); track superState) {
          <mat-option
            [value]="superState.key"
            class="super-state {{superState.value?.class}}"
            >
            <mat-icon [svgIcon]="superState.value?.icon || ''"></mat-icon>
            {{superState.value?.tooltip}}
          </mat-option>
        }
      </mat-select>
    </mat-form-field>
  }

  @if (advancedMode) {
    <mat-form-field appearance="outline">
      <mat-label>Filtername</mat-label>
      <input
        matInput
        [(ngModel)]="filter.label"
        placeholder=""
        data-cy="comment-diag-name"
        required>
    </mat-form-field>
  }


</mat-dialog-content>

<mat-dialog-actions>
  <button
    mat-raised-button
    type="submit"
    [mat-dialog-close]="filter"
    [disabled]="!filter.label || !filter.value || !isValid"
    data-cy="comment-diag-submit"
    >
    Speichern
  </button>
  <button mat-raised-button [mat-dialog-close]="false">
    Abbrechen
  </button>
  <p>
    <mat-slide-toggle [(ngModel)]="advancedMode">Erweiterter Modus</mat-slide-toggle>
  </p>
</mat-dialog-actions><h1 mat-dialog-title>{{ dialogData.title }}</h1>

<mat-dialog-content>
  <p>
    {{ dialogData.content }}
  </p>
  <p>
    Die maximale Zeit Ihrer aktuellen Auswahl beträgt: {{ dialogData.remainingTime }} Minute(n)
  </p>
  <input matInput type="number" id="setTimer" required min="1" [max]="dialogData.remainingTime" [formControl]="setTime">
  <span> Minute(n)</span>
</mat-dialog-content>

<mat-dialog-actions>
  <button mat-raised-button (click)="confirm()">{{ dialogData.confirmbuttonlabel }}</button>
  <button mat-raised-button [mat-dialog-close]="false">{{ dialogData.cancelbuttonlabel }}</button>
</mat-dialog-actions>

